<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/audit.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/contribution_service.php';require_once __DIR__.'/report_error.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405);$auth=requireAuth();$uid=authTenantId($auth);$actorId=authActorId($auth);$d=json_decode(file_get_contents('php://input'),true)?:[];
    $contribution=strtoupper(trim((string)($d['contribution']??'')));$basis=strtoupper(trim((string)($d['basis_kind']??'')));$rate=contributionDecimal($d['rate']??'','Rate');$from=(string)($d['effective_from']??'');$to=trim((string)($d['effective_to']??''))?:null;$legal=trim((string)($d['legal_basis']??''));
    if(!in_array($contribution,['TCL','TFP','FOPROLOS'],true)||!in_array($basis,['TURNOVER','GROSS_PAYROLL','MANUAL'],true)||bccomp($rate,'100',6)>0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||($to!==null&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$to<$from)))throw new InvalidArgumentException('Invalid contribution configuration');
    $conn=db();requirePermission($conn,$uid,'reports.view');$conn->begin_transaction();$s=$conn->prepare('INSERT INTO erp_contribution_configs(user_id,contribution,basis_kind,rate,legal_basis,effective_from,effective_to,created_by) VALUES(?,?,?,?,?,?,?,?)');$s->bind_param('issdsssi',$uid,$contribution,$basis,$rate,$legal,$from,$to,$actorId);$s->execute();$id=(int)$s->insert_id;$s->close();auditLog($conn,$uid,$actorId,'CONTRIBUTION_CONFIG.CREATED','CONTRIBUTION_CONFIG',$id,null,['contribution'=>$contribution,'basis_kind'=>$basis,'rate'=>$rate,'legal_basis'=>$legal,'effective_from'=>$from,'effective_to'=>$to]);$conn->commit();jsonResponse(['success'=>true,'id'=>$id]);
}catch(Throwable $e){if(isset($conn))try{$conn->rollback();}catch(Throwable $ignored){}reportFailureResponse($e,'Could not save the contribution configuration.','CONTRIBUTION_CONFIG_SAVE_FAILED');}
